solution.solution.cpp:
#include <cstdint>
#include <optional>
#include <span>
#include <string_view>
#include <vector>

std::vector<std::string_view> splitWords(std::string_view text)
{
    std::vector<std::string_view> words;
    std::size_t i{ 0 };
    while (i < text.size())
    {
        while (i < text.size() && text[i] == ' ') ++i;
        const std::size_t start{ i };
        while (i < text.size() && text[i] != ' ') ++i;
        if (i > start) words.push_back(text.substr(start, i - start));
    }
    return words;
}

std::uint32_t checksum(std::span<const std::uint8_t> bytes)
{
    std::uint32_t sum{ 0 };
    for (std::uint8_t b : bytes) sum = sum * 31u + b;
    return sum;
}

std::optional<std::span<const std::uint8_t>> nextField(std::span<const std::uint8_t>& rest)
{
    if (rest.empty()) return std::nullopt;
    const std::size_t length{ rest[0] };
    if (rest.size() < 1 + length) return std::nullopt;
    const auto field{ rest.subspan(1, length) };
    rest = rest.subspan(1 + length);
    return field;
}

unitTests:
#include <string>
TEST("words are views into the text") {
    const std::string line{ "  move   north quickly " };
    const auto words{ splitWords(line) };
    CHECK_EQ(words.size(), 3u);
    if (words.size() == 3)
    {
        CHECK(words[0] == "move"); CHECK(words[1] == "north"); CHECK(words[2] == "quickly");
        CHECK(words[0].data() == line.data() + 2);
        CHECK(words[2].data() == line.data() + 15);
    }
    CHECK(splitWords("").empty());
    CHECK(splitWords("    ").empty());
    CHECK_EQ(splitWords("one").size(), 1u);
}
TEST("checksum over a span") {
    const std::uint8_t bytes[]{ 1, 2, 3 };
    CHECK_EQ(checksum(bytes), 1026u);
    CHECK_EQ(checksum(std::span<const std::uint8_t>(bytes).first(2)), 33u);
    CHECK_EQ(checksum({}), 0u);
    std::vector<std::uint8_t> many(1000, 255);
    CHECK_EQ(checksum(many), checksum(std::span<const std::uint8_t>(many.data(), many.size())));
}
TEST("length-prefixed fields") {
    const std::uint8_t packet[]{ 3, 'a', 'b', 'c', 0, 2, 'x', 'y' };
    std::span<const std::uint8_t> rest{ packet };
    auto f1{ nextField(rest) };
    CHECK(f1.has_value());
    if (f1) { CHECK_EQ(f1->size(), 3u); CHECK(f1->data() == packet + 1); }
    auto f2{ nextField(rest) };
    CHECK(f2.has_value());
    if (f2) CHECK(f2->empty());
    auto f3{ nextField(rest) };
    CHECK(f3.has_value());
    if (f3) { CHECK_EQ((*f3)[1], 'y'); }
    CHECK(rest.empty());
    CHECK(!nextField(rest).has_value());
}
TEST("a truncated field leaves rest alone") {
    const std::uint8_t packet[]{ 5, 'a', 'b' };
    std::span<const std::uint8_t> rest{ packet };
    CHECK(!nextField(rest).has_value());
    CHECK_EQ(rest.size(), 3u);
    CHECK(rest.data() == packet);
}

